#include "tigersheets/main_window.hpp"
#include "tigersheets/grid.hpp"
#include <QApplication>
#include <QMenu>
#include <QMessageBox>
#include <QTableView>
#include <QTemporaryDir>
#include <QTest>
#include <QTimer>
#include <QToolButton>
#include <iostream>
#include <stdexcept>
using namespace tigersheets;
namespace {
void require(bool okay,const char* message){if(!okay)throw std::runtime_error(message);}
struct Fixture {
 MainWindow window;QTableView* grid;WorksheetModel* model;QToolButton* button;
 Fixture(){window.resize(2100,720);window.show();window.activateWindow();QApplication::processEvents();grid=window.findChild<QTableView*>("worksheet.grid");model=dynamic_cast<WorksheetModel*>(grid->model());button=window.findChild<QToolButton*>("home.mergeCenter");require(model&&button,"actual Home merge command exists");const auto id=model->sheetId().toStdString();require(model->apply(Json::array({{{"type","set_sheet_layout"},{"sheet",id},{"mergedRanges",Json::array({{{"row1",1},{"col1",1},{"row2",2},{"col2",1}},{{"row1",1},{"col1",2},{"row2",1},{"col2",4}}})}},{{"type","set_cell"},{"sheet",id},{"row",1},{"col",1},{"input","Description"}},{{"type","set_cell"},{"sheet",id},{"row",1},{"col",2},{"input","Consolidated Statements of Cash"},{"style",{{"bold",true},{"note","retain"}}}},{{"type","set_cell"},{"sheet",id},{"row",2},{"col",2},{"input","102"}}})),"prepare native adjacent imported-style horizontal and vertical merges");grid->setCurrentIndex(model->index(0,1));grid->selectionModel()->select(QItemSelection(model->index(0,1),model->index(0,3)),QItemSelectionModel::ClearAndSelect);window.executeCommand("view.ribbon");grid->setFocus();QApplication::processEvents();}
 void open(){window.activateWindow();grid->setFocus();QApplication::processEvents();QTest::keyClick(grid,Qt::Key_Alt);QTest::keyClick(grid,Qt::Key_H);QApplication::processEvents();}
 const Json& sheet(){return window.currentSession().snapshotView().at("sheets")[0];}
};
void pointerToggle(){
 Fixture f;f.grid->setCurrentIndex(f.model->index(1,1));QTest::mouseClick(f.grid->viewport(),Qt::LeftButton,Qt::NoModifier,QPoint(f.grid->columnViewportPosition(2)+f.grid->columnWidth(2)/2,f.grid->rowViewportPosition(0)+f.grid->rowHeight(0)/2));QApplication::processEvents();const auto before=f.window.currentSession().snapshot();const auto selection=f.grid->selectionModel()->selection();require(f.grid->selectionModel()->isSelected(f.model->index(0,1))&&!f.grid->selectionModel()->isSelected(f.model->index(0,0)),"actual interior mouse click selects the merged anchor without its adjacent vertical merge");std::cout<<"native merged selection fragments="<<selection.size()<<'\n';f.open();require(f.button->isVisible()&&f.button->isEnabled(),"Home Merge and Center is a functional control, not a disabled placeholder");require(f.button->isCheckable()&&f.button->isChecked(),"Home merge state follows an existing selected merged header");require(!f.button->icon().isNull()&&f.button->toolButtonStyle()==Qt::ToolButtonIconOnly&&!f.button->toolTip().isEmpty(),"functional merge control preserves the compact graphical ribbon");QTest::mouseClick(f.button,Qt::LeftButton,Qt::NoModifier,{7,f.button->height()/2});QApplication::processEvents();require(f.sheet().at("mergedRanges")==Json::array({{{"row1",1},{"col1",1},{"row2",2},{"col2",1}}})&&f.grid->columnSpan(0,1)==1&&f.grid->rowSpan(0,0)==2,"clicking the main merge control unmerges only the selected existing header");require(f.sheet().at("cells")==before.at("sheets")[0].at("cells")&&f.grid->selectionModel()->selection()==selection,"Home unmerge preserves every value, style, note and selection");require(f.window.executeCommand("undo")&&f.window.currentSession().snapshotView().at("sheets")==before.at("sheets"),"one Undo restores the Home-unmerged header exactly");require(f.button->isChecked(),"Undo refreshes the Home merged-state indicator");
}
void keyboardMenu(){
 Fixture f;f.grid->selectionModel()->select(QItemSelection(f.model->index(0,1),f.model->index(0,1)),QItemSelectionModel::ClearAndSelect);const auto before=f.window.currentSession().snapshot();f.open();QTest::keyClick(f.grid,Qt::Key_M);QApplication::processEvents();auto* menu=f.window.findChild<QMenu*>("home.mergeMenu");require(menu&&menu->isVisible()&&QApplication::activePopupWidget()==menu,"Alt H M opens explicit merge options instead of silently toggling the sheet");require(f.window.currentSession().snapshot()==before,"opening merge options creates no edit");auto* unmerge=menu->findChild<QAction*>("home.merge.unmerge");require(unmerge&&unmerge->isEnabled(),"explicit Unmerge is available for an anchor-only selection");QTest::keyClick(menu,Qt::Key_U);QApplication::processEvents();require(f.sheet().at("mergedRanges")==Json::array({{{"row1",1},{"col1",1},{"row2",2},{"col2",1}}})&&f.sheet().at("cells")==before.at("sheets")[0].at("cells"),"Alt H M U unmerges the selected imported header and retains adjacent merges and content");require(f.window.executeCommand("undo")&&f.window.currentSession().snapshotView().at("sheets")==before.at("sheets"),"keyboard unmerge is one exact Undo");f.open();QTest::keyClick(f.grid,Qt::Key_M);QApplication::processEvents();require(menu->isVisible(),"merge menu reopens after Undo");QTest::keyClick(menu,Qt::Key_Escape);QApplication::processEvents();require(f.window.currentSession().snapshotView().at("sheets")==before.at("sheets"),"Escape cancels merge options without changing the workbook");
}
void pointerMenu(){
 Fixture f;const auto before=f.window.currentSession().snapshot();bool opened=false;std::exception_ptr error;f.open();QTimer::singleShot(0,[&]{auto* menu=f.window.findChild<QMenu*>("home.mergeMenu");try{require(menu&&menu->isVisible(),"split arrow opens native merge options");opened=true;auto* unmerge=menu->findChild<QAction*>("home.merge.unmerge");require(unmerge&&unmerge->isEnabled(),"pointer menu exposes enabled Unmerge Cells");QTest::mouseClick(menu,Qt::LeftButton,Qt::NoModifier,menu->actionGeometry(unmerge).center());}catch(...){error=std::current_exception();if(menu)menu->close();}});QTest::mouseClick(f.button,Qt::LeftButton,Qt::NoModifier,{f.button->width()-3,f.button->height()/2});QApplication::processEvents();if(error)std::rethrow_exception(error);require(opened&&f.grid->columnSpan(0,1)==1&&f.grid->rowSpan(0,0)==2&&f.sheet().at("cells")==before.at("sheets")[0].at("cells"),"pointer Unmerge preserves adjacent spans and every cell");require(f.window.executeCommand("undo")&&f.window.currentSession().snapshotView().at("sheets")==before.at("sheets"),"pointer menu Unmerge is one exact Undo");
}

void disjointSelection(){
 Fixture f;QItemSelection areas;areas.select(f.model->index(0,1),f.model->index(0,1));areas.select(f.model->index(3,5),f.model->index(3,5));f.grid->selectionModel()->select(areas,QItemSelectionModel::ClearAndSelect);const auto before=f.window.currentSession().snapshot();f.open();require(f.button->isEnabled(),"Home unmerge remains available when disjoint areas intersect an existing merged cell");QTest::keyClick(f.grid,Qt::Key_M);QApplication::processEvents();auto* menu=f.window.findChild<QMenu*>("home.mergeMenu");require(menu&&menu->isVisible(),"disjoint selection can open explicit unmerge options");auto* center=menu->findChild<QAction*>("home.merge.center");auto* cells=menu->findChild<QAction*>("home.merge.cells");auto* unmerge=menu->findChild<QAction*>("home.merge.unmerge");require(center&&!center->isEnabled()&&cells&&!cells->isEnabled()&&unmerge&&unmerge->isEnabled(),"disjoint merge menu disables destructive creation while retaining non-destructive Unmerge");QTest::keyClick(menu,Qt::Key_U);QApplication::processEvents();require(f.sheet().at("mergedRanges")==Json::array({{{"row1",1},{"col1",1},{"row2",2},{"col2",1}}})&&f.sheet().at("cells")==before.at("sheets")[0].at("cells"),"disjoint Home unmerge touches selected spans without inventing a bounding-box merge");require(f.window.executeCommand("undo")&&f.window.currentSession().snapshotView().at("sheets")==before.at("sheets"),"disjoint Home unmerge is one exact Undo");
}

void safeMerge(){
 Fixture f;require(f.model->setData(f.model->index(3,5),"Keep",Qt::EditRole)&&f.model->setData(f.model->index(3,6),"Other value",Qt::EditRole),"prepare a genuine merge requiring confirmation");f.grid->setCurrentIndex(f.model->index(3,5));f.grid->selectionModel()->select(QItemSelection(f.model->index(3,5),f.model->index(3,6)),QItemSelectionModel::ClearAndSelect);const auto before=f.window.currentSession().snapshot();bool warned=false;f.open();QTimer::singleShot(0,[&]{if(auto* warning=qobject_cast<QMessageBox*>(QApplication::activeModalWidget())){warned=warning->text().contains("upper-left");QTest::mouseClick(warning->button(QMessageBox::No),Qt::LeftButton);}});QTest::mouseClick(f.button,Qt::LeftButton,Qt::NoModifier,{7,f.button->height()/2});QApplication::processEvents();require(warned&&f.window.currentSession().snapshot()==before&&!f.button->isChecked(),"Home merge cancellation preserves both values, layout, history and button state");warned=false;f.open();QTest::keyClick(f.grid,Qt::Key_M);QApplication::processEvents();auto* menu=f.window.findChild<QMenu*>("home.mergeMenu");require(menu&&menu->isVisible(),"Home merge menu exposes its keyboard merge choices");QTimer::singleShot(0,[&]{if(auto* warning=qobject_cast<QMessageBox*>(QApplication::activeModalWidget())){warned=true;QTest::mouseClick(warning->button(QMessageBox::Yes),Qt::LeftButton);}});QTest::keyClick(menu,Qt::Key_C);QApplication::processEvents();require(warned&&f.grid->columnSpan(3,5)==2&&f.model->raw(3,5)=="Keep"&&f.model->raw(3,6).isEmpty()&&f.model->cellStyle(3,5).value("alignment",std::string())=="center"&&f.button->isChecked(),"Home Merge and Center uses native confirmation and reflects the completed merge");require(f.window.executeCommand("undo")&&f.window.currentSession().snapshotView().at("sheets")==before.at("sheets"),"one Undo restores all confirmed merge values and layout");
}

}
int main(int argc,char** argv){QApplication app(argc,argv);QTemporaryDir state;qputenv("TIGERSHEETS_STATE_DIR",state.path().toUtf8());try{const std::string mode=argc>1?argv[1]:"all";if(mode=="all"||mode=="pointer")pointerToggle();if(mode=="all"||mode=="keyboard")keyboardMenu();if(mode=="all"||mode=="safe")safeMerge();if(mode=="all"||mode=="menu")pointerMenu();if(mode=="all"||mode=="disjoint")disjointSelection();std::cout<<"Native Home merge workflows passed\n";}catch(const std::exception& error){std::cerr<<"FAILED: "<<error.what()<<'\n';return 1;}}
